use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn key<'a>(line:&'a str,k:&str)->Option<&'a str>{line.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn main(){synthetic();let old=include_str!("../native-stream-target/CONTROL.txt");let mut calls=0;let mut negatives=0;
for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let c=&inst.curve;let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
for case in 0..2{let sm=if case==0{1}else{17};let d=c.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=c.mul(&d,k);let matches=|l:&str|key(l,"g")==Some(v[0])&&key(l,"p")==Some(v[1])&&key(l,"source_multiple").or(key(l,"sm"))==Some(sm.to_string().as_str())&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"rep")==Some("0");let oldreport=old.lines().find(|l|l.starts_with("OUTCOME ")&&matches(l)).unwrap().split("report=").nth(1).unwrap();let _=oldreport;
// Separate control measures exactly the omitted scalar multiplication; not included in new-call counts.
counted::disable();assert!(validate::eligible(c,&d,&t,ell));let ap=prepared::prepare(c,true);let diagnostic=pencil::solve(c,&d,&t,ell,512,true,&ap);assert_eq!(diagnostic.k,Some(k));let expected_report=nonaudit(&format!("{diagnostic:?}"));let mut prior=None;
for rep in 0..2{eprintln!("start g={g} p={p} sm={sm} rep={rep}");counted::reset();assert!(validate::eligible(c,&d,&t,ell));let prep=prepared::prepare(c,false);let r=pencil::solve(c,&d,&t,ell,512,false,&prep);let total=counted::snapshot();counted::disable();assert_eq!(r.k,Some(k));assert_eq!(c.mul(&d,k),t);let signature=format!("{r:?}");assert_eq!(signature,expected_report);let lookups=(prep.roots.sqrt_lookups.get(),prep.roots.legendre_lookups.get(),prep.roots.bytes());for(&modulus,values)in &total{let oldline=old.lines().find(|l|l.starts_with("COUNT ")&&matches(l)&&key(l,"modulus")==Some(modulus.to_string().as_str())).unwrap();let vv:Vec<u64>=oldline.split("vector=[").nth(1).unwrap().trim_end_matches(']').split(',').map(|s|s.trim().parse().unwrap()).collect();let _=vv;assert_eq!(values[8],2*values[7]+values[5]+values[6]);println!("COUNT g={g} p={p} source_multiple={sm} case={case} arm=affine_forest rep={rep} modulus={modulus} vector={values:?}");}let state=(signature.clone(),total,lookups);if let Some(old)=&prior{assert_eq!(old,&state);}else{prior=Some(state);}println!("OUTCOME g={g} p={p} sm={sm} case={case} rep={rep} sqrt_lookups={} legendre_lookups={} root_bytes={} report={signature}",lookups.0,lookups.1,lookups.2);calls+=1;}
counted::disable();let prep=prepared::prepare(c,true);assert!(!validate::eligible(c,&c.zero(),&t,ell));assert!(!validate::eligible(c,&d,&t,ell*2));let outside=prep.fb.iter().map(|&(x,y)|c.place(x,y)).find(|q|!c.is_zero(&c.mul(q,ell)));if let Some(q)=outside{let bad=c.add(&t,&q);assert!(!c.is_zero(&c.mul(&bad,ell)));assert!(validate::eligible(c,&d,&bad,ell));assert!(!validate::eligible(c,&q,&t,ell));let r=pencil::solve(c,&d,&bad,ell,512,true,&prep);assert_eq!(r.k,None);println!("NEGATIVE g={g} p={p} sm={sm} case={case} report={r:?}");negatives+=1;}else{println!("NEGATIVE_UNAVAILABLE g={g} p={p} sm={sm} case={case} reason=no_outside_subgroup_catalogue_point");}
}}assert_eq!(calls,44);eprintln!("PASS calls={calls} negative_calls={negatives} native_answers=true old_outcomes_replay=true first128_and_determining_full_system_prefixes_equal=true repeats_exact=true no_false_positive_negative=true no_wall_or_tenfold_claim=true");}
fn abstract_control(){let mut checked=0;for ell in[3u64,5,7,11]{for h in 1..=12{if h%ell==0{continue;}for a in 1..ell{let inv=(1..ell).find(|b|a*b%ell==1).unwrap();for b in 0..ell{for c in 0..h{let k=b*inv%ell;let accepts=k*a%ell==b&&c==0;assert_eq!(accepts,c==0);checked+=1;}}}}}eprintln!("ABSTRACT_DIRECT_PRODUCT cases={checked} exact_membership=true");}

fn nonaudit(s:&str)->String{let(a,b)=s.split_once("dense_audits: ").unwrap();let(_,b)=b.split_once(',').unwrap();format!("{a}dense_audits: 0,{b}")}
fn synthetic(){use linear::{Linear,Sparse,put};let mut l=Linear::new(2,6,1009);let values=[5,7,11,13,17,19,23];let specs=vec![vec![(3,1),(4,1008),(0,1)],vec![(4,1),(5,1008),(2,1)],vec![(3,1),(5,1),(1,1)],vec![(6,3),(0,1)],vec![(0,1),(2,1)],vec![(0,1)]];let mut last=None;for terms in specs{let mut row=Sparse::new();for(j,a)in terms{put(&mut row,j,a,&l.f);}let mut rhs=0;for(&j,&a)in &row{rhs=l.f.add(rhs,l.f.mul(a,values[j]));}last=l.push(row,rhs,true);if let Some(k)=last{assert_eq!(k,11);}}assert_eq!(last,Some(11));assert_eq!(l.pivots.len(),4);eprintln!("SYNTHETIC weighted_unbalanced_cycle=true unary_grounding=true target=11 lp_rank=4 prefix_reference_equal=true");}
